const fs=require('fs'),path=require('path');
process.chdir(__dirname);
const OUT=process.env.OUT_DIR?path.resolve(process.env.OUT_DIR):path.join(__dirname,'dist');
let h=fs.readFileSync('shell.html','utf8');
const hero='data:image/jpeg;base64,'+fs.readFileSync('img/hero.jpg').toString('base64');
const homebg='data:image/jpeg;base64,'+fs.readFileSync('img/homebg.jpg').toString('base64');
h=h.replace('/*__FONTS__*/',()=>fs.readFileSync('fonts/fonts.css','utf8').replace(/__FONT_(\w+)__/g,(m,k)=>'data:font/woff2;base64,'+fs.readFileSync('fonts/'+k+'.woff2').toString('base64'))).replace('/*__NATIVE__*/',()=>fs.readFileSync('node_modules/@capacitor/core/dist/capacitor.js','utf8').replace(/\/\/# sourceMappingURL=.*$/m,'')+'\n'+fs.readFileSync('native.js','utf8')).replace('/*__CSS__*/',()=>fs.readFileSync('style.css','utf8').replace(/__IT_(\w+)__/g,(m,k)=>'data:image/jpeg;base64,'+fs.readFileSync('img/it_'+k+'.jpg').toString('base64')).split('__HERO__').join(hero).split('__HOMEBG__').join(homebg).split('__PT_product__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_product.jpg').toString('base64')).split('__PT_ops__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_ops.jpg').toString('base64')).split('__PT_market__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_market.jpg').toString('base64')).split('__PT_admin__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_admin.jpg').toString('base64')).split('__PT_content__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_content.jpg').toString('base64')).split('__PT_event__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_event.jpg').toString('base64')).split('__PT_research__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_research.jpg').toString('base64')).split('__PT_training__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_training.jpg').toString('base64')).split('__PT_mission__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_mission.jpg').toString('base64')).split('__PT_care__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_care.jpg').toString('base64')).split('__PT_finance__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_finance.jpg').toString('base64')).split('__PT_tech__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_tech.jpg').toString('base64')).split('__PT_media__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_media.jpg').toString('base64')).split('__PT_worship__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_worship.jpg').toString('base64')).split('__PT_hr__').join('data:image/jpeg;base64,'+fs.readFileSync('img/pt_hr.jpg').toString('base64')).split('__WC_desk__').join('data:image/jpeg;base64,'+fs.readFileSync('img/wc_desk.jpg').toString('base64')).split('__WC_lake__').join('data:image/jpeg;base64,'+fs.readFileSync('img/wc_lake.jpg').toString('base64')).split('__PROJHERO__').join('data:image/jpeg;base64,'+fs.readFileSync('img/proj_hero.jpg').toString('base64')).split('__G4_voice__').join('data:image/jpeg;base64,'+fs.readFileSync('img/g4_voice.jpg').toString('base64')).split('__G4_video__').join('data:image/jpeg;base64,'+fs.readFileSync('img/g4_video.jpg').toString('base64')).split('__G4_text__').join('data:image/jpeg;base64,'+fs.readFileSync('img/g4_text.jpg').toString('base64')).split('__G4_ai__').join('data:image/jpeg;base64,'+fs.readFileSync('img/g4_ai.jpg').toString('base64')).split('__G4_file__').join('data:image/jpeg;base64,'+fs.readFileSync('img/g4_file.jpg').toString('base64'))).replace('/*__ENGINE__*/',()=>fs.readFileSync('engine.js','utf8')).replace('/*__APP__*/',()=>fs.readFileSync('app.js','utf8').replace('__ENOS__','data:image/jpeg;base64,'+fs.readFileSync('img/enos.jpg').toString('base64')));
fs.mkdirSync(OUT,{recursive:true});
fs.writeFileSync(path.join(OUT,'team-ops.html'),h);
fs.writeFileSync(path.join(OUT,'index.html'),h); // Netlify 拖拽部署用
fs.mkdirSync(path.join(OUT,'app'),{recursive:true});
fs.writeFileSync(path.join(OUT,'app','index.html'),h); // Capacitor webDir（iOS/Android App）
// syntax check every inline script
const scripts=[...h.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m=>m[1]);
scripts.forEach((s,i)=>{ new Function(s); });
console.log('built',h.length,'bytes, scripts ok:',scripts.length);
